    for (int i = n - 1; i >= 0; --i) {
        dp[i][0] = min(arr[i] + dp[i + 1][0], dp[i + 1][1]);
        dp[i][1] = max(arr[i] + dp[i + 1][0], dp[i + 1][1]);
