#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll n, sum = 0;
vector<ll> arr;
vector<array<ll, 2>> dp;
vector<array<bool, 2>> visited;

ll go(ll idx, int ch) {
    if (idx == n) return 0;

    if (visited[idx][ch]) return dp[idx][ch];
    visited[idx][ch] = true;

    if (ch) {
        return dp[idx][ch] = max(arr[idx] + go(idx + 1, 0),
                                 go(idx + 1, 1));
    }

    return dp[idx][ch] = min(arr[idx] + go(idx + 1, 0),
                             go(idx + 1, 1));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    arr.resize(n);
    dp.resize(n);
    visited.resize(n);

    for (ll &x : arr) {
        cin >> x;
        sum += x;
    }

    ll bob = go(0, 0);
    cout << bob << ' ' << sum - bob << '\n';

    return 0;
}

